      "code": "from decimal import Decimal
from hypothesis import given, strategies as st, settings, assume
import impl


def is_tie(x):
    s = x * 1000
    return s == s.to_integral_value() and int(s) % 10 == 5


def apply_pct(amount, pct):
    return amount * (Decimal(1) - pct / Decimal(100))


@given(
    st.integers(min_value=100, max_value=100000),
    st.integers(min_value=0, max_value=99999),
    st.integers(min_value=0, max_value=99999),
)
@settings(max_examples=150)
def test_rounds_after_each_step_not_only_at_end(subtotal_c, p1_m, p2_m):
    subtotal = Decimal(subtotal_c) / 100
    p1, p2 = Decimal(p1_m) / 1000, Decimal(p2_m) / 1000
    exact1 = apply_pct(subtotal, p1)
    assume(not is_tie(exact1))
    r1 = exact1.quantize(Decimal('0.01'))
    correct = apply_pct(r1, p2)
    buggy = apply_pct(exact1, p2)
    assume(not is_tie(correct) and not is_tie(buggy))
    r_correct = correct.quantize(Decimal('0.01'))
    r_buggy = buggy.quantize(Decimal('0.01'))
    assume(r_correct != r_buggy)
    discounts = [
        {'kind': 'percent', 'value': str(p1)},
        {'kind': 'percent', 'value': str(p2)},
    ]
    out = impl.apply_discounts(str(subtotal), discounts)
    assert Decimal(out) == r_correct
